-- 
-- Table structure for table `blog_content`
-- 

CREATE TABLE `blog_content` (
  `content_id` int(10) NOT NULL auto_increment,
  `topic` varchar(100) NOT NULL default '',
  `message` longtext NOT NULL,
  `category_id` int(10) NOT NULL default '0',
  `submit_day` int(2) NOT NULL default '0',
  `submit_month` int(2) NOT NULL default '0',
  `submit_year` int(4) NOT NULL default '0',
  `submit_time` time NOT NULL default '00:00:00',
  `author_ip` varchar(15) NOT NULL default '',
  `is_show` enum('show','hide') NOT NULL default 'show',
  `is_recommend` enum('yes','no') NOT NULL default 'no',
  `comment_option` enum('allow-show','allow-hide','notallow') NOT NULL default 'allow-show',
  `hits` bigint(20) NOT NULL default '0',
  `author_user_id` int(10) NOT NULL default '0',
  PRIMARY KEY  (`content_id`),
  KEY `author_user_id` (`author_user_id`)
) TYPE=MyISAM AUTO_INCREMENT=111 ;

