INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (75, 'Content แรกของ blog.soi13.com', 'วันนี้วันที่ 12 ก.พ. 2549<br><br>ในที่สุด blog.soi13.com ก็เสร็จซะที <img src="http://blog.soi13.com/images/smilies/biggrin.gif"><br><br>ต่อไปก็เป็นช่วงทดลองใช้งาน + หาบัคหละนะ<br><br>ขอเชิญชวนเพื่อนๆ พี่ๆ น้องๆ มาร่วมจับแมลงกันนะคร๊าบ ~~<br>', 1, 12, 2, 2006, '13:39:57', '58.64.100.189', 'show', 'no', 'allow-show', 20, 29);
INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (76, '[JDrama] Beautiful Life : ความฝันของเธอ มีฉันอยู่บ้างไหม', 'Beautiful Life<BR><IMG height=191 src="http://album.romerun.com/budgetseries/folder/25593/album/42947/image/871152/pic/original.jpg" width=227 border=0><BR>japanese drama ที่ออกฉายที่ญี่ปุ่นในปีค.ศ. 2000 (พ.ศ. 2543) และได้สร้างปรากฎการณ์ให้กับวงการ drama ของญี่ปุ่น<BR>ด้วยการมี viewership rating หรือจำนวนผู้ชมสูงถึง 41.3% ในตอนจบซึ่งถือเป็น rating สูงสุดในประวัติศาสตร์ของวงการ dramaสมัยใหม่ของญี่ปุ่น<BR>และกวาดรางวัลจากการประกาศผลรางวัล Japanese Drama Academy Awardครั้งที่ 24 ไปทั้งหมดถึง 11 รางวัล (จากทั้งหมด 14 รางวัล)ซึ่งทั้งหมดล้วนแต่เป็นรางวัลสำคัญด้วย<BR><BR>นักแสดง :<BR>Kimura Takuya รับบทเป็น Okishima Shuji<BR>Tokiwa Takako รับบทเป็น Machida Kyoko<BR>Ikeuchi Hiroyuki รับบทเป็น Okabe Takumi (รุ่นน้องของชูจิ)<BR>Watabe Atsuro รับบทเป็น Machida Masao (พี่ชายของเคียวโกะ)<BR>Mizuno Miki รับบทเป็น Tamura Sachie (เพื่อนสนิทของเคียวโกะ)<BR>Matoba Koji รับบทเป็น Miyama Kouzou<BR>Nishikawa Takanori รับบทเป็น Kawamura Satoru<BR>Hara Chiaki รับบทเป็น Ozawa Mayumi<BR>Koyuki<BR><BR>เนื้อเรื่องย่อ :<BR>มาชิดะ เคียวโกะ หญิงสาวผู้โชคร้าย เธอถูกโรคร้ายคุกคามทำให้ต้องพิการจนต้องนั่งรถเข็นไปจนตลอดชีวิต แต่ถึงกระนั้นตัวเธอเองก็ยังคงมีกำลังใจในการดำเนินชีวิต<BR>และใช้ชีวิตอยู่ด้วยรอยยิ้มเสมอทำให้ไม่มีใครรับรู้ได้ถึงความอ้างว้าง ความกลัวและความหนาวเหน็บในหัวใจของเธอซึ่งเธอซ่อนมันไว้ในซอกหลืบของหัวใจที่แม้แต่<BR>ตัวเองก็ยังคงพยายามจะลืมมันไป ... จนกระทั่งวันหนึ่งเธอได้รู้จักกับโอคิชิมะ ชูจิ สไตล์ลิสหนุ่มเลือดร้อนผู้ซึ่งใฝ่ฝันจะเป็นช่างตัดผมที่มีชื่อเสียง แม้การพบกันครั้งแรก<BR>จะไม่ใช่การพบกันที่ดีนักแต่ความสัมพันธ์ของทั้งคู่กลับค่อยๆพัฒนาและผูกพันกันอย่างลึกซึ้งแต่ความรักระหว่างคนสองคนซึ่งต่างกันสุดขั้วกลับต้องพบกับอุปสรรคมากมาย<BR>ทั้งความกังวลในจิตใจของเคียวโกะซึ่งตอกย้ำตัวเองอยู่เสมอว่าตนเองนั้นเป็นคนพิการต่างกับชูจิผู้ซึ่งมีอนาคตอันสว่างสดใสรออยู่ข้างหน้ามากมายเหลือเกินทั้งคนรักเก่า<BR>ของชูจิซึ่งเลิกกับสามีและไม่มีทั้งที่พึ่งทางกายและที่พึ่งทางใจและยังมีพี่ชายของเคียวโกะ ผู้ซึ่งไม่ไว้ใจใครและไม่คิดว่าจะมีใครที่จะมาเข้าใจจิตใจของน้องสาวได้เหมือน<BR>ดังเช่นครอบครัวของตนเองทำให้เขาพยายามกีดกันผู้ชายทุกคนที่จะเข้ามาในชีวิตของน้องสาวและยังมีโรคร้ายซึ่งคอยกัดกินทั้งร่างกายและจิตใจของเคียวโกะตลอดเวลา ...<BR><BR>วิจารณ์ :<BR>เนื้อเรื่อง - ดำเนินเรื่องได้อย่างสม่ำเสมอ และเป็นธรรมชาติ ค่อยๆแสดงอารมณ์และความผูกพันของพระเอกและนางเอกได้อย่างลึกซึ้ง<BR>นักแสดง - ตัวแสดงหลักทุกคนแสดงได้อย่างหาที่ติไม่ได้ทั้งตัวพระเอกเอง ที่ใจร้อน แต่ก็มีความรักให้กับนางเอกอย่างที่สุดและนางเอกซึ่งเป็นคนพิการ แต่ก็มีรอยยิ้มให้กับผู้อื่นอยู่เสมอ<BR><BR>คะแนน : 9/10 หักไป 1 คะแนนเต็ม เนื่องจากจบเศร้า T_T ส่วนที่เหลือ หาที่ติไม่ได้จริงๆ<BR><BR>รางวัลที่ได้รับ :<BR>Japanese 45th Television Academy Awards<BR>Best drama<BR>Best actor: Kimura Takuya<BR>Best actress : Takako Tokiwa<BR>Best supporting actor : Watabe Atsuro<BR>Best supporting actress: Mizuno Miki<BR>Best newcomer: Nishikawa Takanori<BR>Best scriptwriter: Eriko Kitagawa<BR>Best theme song: Konya Tsuki no Mieru oka ni - B&#39;z<BR>Best director<BR>Best cast: Beautiful life<BR>Best opening: Beautiful life', 2, 12, 2, 2006, '14:21:39', '161.246.5.92', 'show', 'yes', 'allow-show', 6, 29);
INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (78, 'Introduce about my Blog', '<div style="text-align: center;"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">Let&#39;s talk this over</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">It&#39;s not like we&#39;re dead</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">Was it something I did?</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">Was it something You said?</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">Don&#39;t leave me hanging</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">In a city so dead</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">Held up so high </font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">On such a breakable thread</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 51, 0);" face="Verdana" size="5"><font size="2">You were all the things I thought I knew</font></font><br style="color: rgb(0, 51, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">And I thought we could be</font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2"><i>[Chorus:]</i></font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">You were everything, everything that I wanted</font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">We were meant to be, supposed to be, but we lost it</font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">And all of the memories, so close to me, just fade away</font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">All this time you were pretending</font></font><br style="color: rgb(0, 102, 0);"></div><div style="text-align: center;"><font style="color: rgb(0, 102, 0);" face="Verdana" size="5"><font size="2">So much for my happy ending</font></font><br style="color: rgb(0, 102, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">Oh oh, oh oh, oh oh...</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">You&#39;ve got your dumb friends</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">I know what they say</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">They tell you I&#39;m difficult</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">But so are they</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">But they don&#39;t know me</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">Do they even know you?</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">All the things you hide from me</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">All the shit that you do</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">You were all the things I thought I knew</font></font><br style="color: rgb(0, 153, 0);"><font style="color: rgb(0, 153, 0);" face="Verdana" size="5"><font size="2">And I thought we could be</font></font><br><font face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2"><i>[Chorus]</i></font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2">It&#39;s nice to know that you were there</font></font><br style="color: rgb(51, 204, 0);"></div><div style="text-align: center; color: rgb(51, 204, 0);"><font face="Verdana" size="5"><font size="2">Thanks for acting like you cared</font></font><br></div><div style="text-align: center;"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2">And making me feel like I was the only one</font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2">It&#39;s nice to know we had it all</font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2">Thanks for watching as I fall</font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2">And letting me know we were done</font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 204, 0);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(51, 204, 0);"><font style="color: rgb(51, 255, 51);" face="Verdana" size="5"><font size="2"><i>[Chorus x2]</i></font></font><br style="color: rgb(51, 255, 51);"><font style="color: rgb(51, 255, 51);" face="Verdana" size="5"><font size="2"></font></font><br style="color: rgb(51, 255, 51);"><font style="color: rgb(51, 255, 51);" face="Verdana" size="5"><font size="2"><i>[x2]</i></font></font><br style="color: rgb(51, 255, 51);"><font style="color: rgb(51, 255, 51);" face="Verdana" size="5"><font size="2">Oh oh, oh oh, oh oh...</font></font><br style="color: rgb(51, 255, 51);"><font style="color: rgb(51, 255, 51);" face="Verdana" size="5"><font size="2">So much for my happy ending</font></font></div><span style="color: rgb(51, 204, 0);"></span>', 1, 12, 2, 2006, '14:30:00', '58.10.209.29', 'show', 'yes', 'allow-show', 11, 35);
INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (77, '[JDrama] Nobuta wo Produce : ปั้น \\"ดิน\\" ให้เป็น \\"ดาว\\"', 'Nobuta wo Produce<BR><IMG height=233 src="http://album.romerun.com/budgetseries/folder/25593/album/42949/image/871186/pic/original.jpg" width=231 border=0><BR>japanese drama ที่ฉายที่ญี่ปุ่นในช่วงเดือนกันยายน-ธันวาคม 2548 โดยมีจุดขายคือดารานำชายทั้งสองคน มีเนื้อหาเกี่ยวกับปัญหาสังคม<BR>ของญี่ปุ่นในยุคปัจจุบันคือปัญหาการกลั่นแกล้งกันในโรงเรียน<BR><BR>นักแสดง :<BR>Kamenashi Kazuya รับบทเป็น Kiritani Shuji<BR>Yamashita Tomohisa รับบทเป็น Kusano Akira<BR>Horikita Maki รับบทเป็น Kotani Nobuko<BR>Toda Erika รับบทเป็น Uehara Mariko<BR>Ukaji Takashi รับบทเป็น Kiritani Satoru<BR>Fukaura Kanako รับบทเป็น Kiritani Shinko<BR>Nakajima Yuto รับบทเป็น Kiritani Koji<BR>Okada Yoshinori รับบทเป็น Yokoyama Takeshi <BR><BR>เนื้อเรื่องย่อ :<BR>คิริทานิ ชูจิ เด็กหนุ่มผู้ร่าเริงอยู่เสมอเป็นคนที่ทุ่มเทเวลาให้กับคนรอบข้าง และมีมนุษยสัมพันธ์อันดีกับทุกๆคนแถมยังมีแฟนที่สุดแสนจะน่ารักอย่าง<BR>อุเอฮาร่า มาริโกะ หญิงสาวจิตใจงามที่เป็นดาวโรงเรียนอีกด้วยแต่ไม่มีใครรู้เลยว่า ตัวจริงของชูจินั้นกลับไม่ได้เป็นอย่างที่ทุกคนเห็นเขาไม่ได้อยาก<BR>จะสุงสิงกับใครๆ หากแต่เพียงต้องการจะเป็นที่นิยมของทุกๆคนเท่านั้นวันหนึ่ง ชูจิได้พบกับหญิงสาวท่าทางประหลาดที่สวนสาธารณะ และกลายเป็นว่า<BR>หญิงสาวคนนั้นเป็นนักเรียนใหม่ของรร.ของเขานั่นเอง เธอชื่อโคทานิโนบูโกะ เด็กหญิงผู้ซึ้งไม่มีความมั่นใจในตัวเองเลยแม้แต่นิดเดียวและเป็นเป้า<BR>ให้คนอื่นๆกลั่นแกล้งอยู่เสมอ ชูจิและคุซาโนะ อากิระจึงตัดสินใจที่จะช่วยโนบูโกะด้วยการ "โปรดิวซ์" เธอให้เธอได้มีชื่อเสียงและได้รับการยอมรับ<BR>ในโรงเรียน ทุกอย่างดูเหมือนจะดำเนินไปได้ด้วยดีจนกระทั่งพวกเขาค้นพบว่ายังมีบางคนที่อยู่ในเงามืดไม่ต้องการให้โนบูโกะได้รับการยอมรับจาก<BR>คนอื่นๆ ...<BR><BR>วิจารณ์ :<BR>เนื้อเรื่อง - ดำเนินเนื้อเรื่องได้เรื่อยๆ ไม่ค่อยมีเหตุการณ์หวือหวาหรือหักมุมอะไร ตัวเรื่องเป็นดราม่าซะเยอะ ไม่ค่อยมีอะไรขำๆหรือมีอะไรให้ตื่นเต้นมาก<BR>นักแสดง - คาดว่าสาวๆคงจะชอบเรื่องนี้ไม่น้อย แต่สำหรับหนุ่มๆอย่างผมมีเข้าตาแค่คนเดียวคือ Toda Erika ซึ่งมารับบทเป็นนางรองส่วนคนอื่นๆนั้นอยู่ในระดับดี โดยเฉพาะนางเอกที่เล่นได้สมบทบาทพอสมควรทีเดียว<BR><BR>คะแนน : 7/10 สำหรับสาวๆที่คลั่งไคล้ดารานำทั้งสองคงให้มากกว่านี้แ่ต่สำหรับตัวผมเอง เรื่องนี้เป็นได้แค่เรื่องดูคั่นเวลาที่ไม่มี dramaเรื่องอื่นๆที่น่าสนใจกว่านี้ให้ดู ตัว dramaเองก็ไม่ถึงกับจัดอยู่ในระดับน่าเบื่อแต่ก็ไม่จัดอยู่ในระดับที่กระตุ้นให้ผมอยากติดตามอย่างต่อเนื่องได้แถมสาวๆในเรื่องยังมีน่ารักเข้าตาอยู่แค่คนเดียวอีกต่างหาก', 2, 12, 2, 2006, '14:23:12', '161.246.5.92', 'show', 'yes', 'allow-show', 14, 29);
