INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (84, 'Munich', '<P>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ในเดือนกันยายน ปี 1972 การโจมตีของผู้ก่อการร้ายในแบบที่ไม่เคยมีมาก่อน ได้ถูกตีแผ่สดๆ ต่อหน้าคนดูโทรทัศน์กว่า 900 ล้านคนทั่วโลก และนำมาซึ่งโลกใหม่แห่งความรุนแรง ที่คาดเดาไม่ได้ </P>\n<P>&nbsp;</P>\n<P align=center><IMG height=339 src="http://www.pappayon.com/preview/2006/munich/images/poster.jpg" width=192></P>\n<P>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;มันคืออาทิตย์ที่ 2 ของการแข่งขันกีฬาโอลิมปิคฤดูร้อน และในมิวนิค เยอรมันตะวันตก เกมส์การแข่งขันที่ได้รับการขนานนามว่าเป็น “โอลิมปิคแห่งความสงบและความสุข” เดินหน้าไปสู่จุดเริ่มต้นอันเร้าใจ เมื่อนักว่ายน้ำ มาร์ก สปิตซ์ และนักยิมนาสติค โอลก้า คอร์บัต ทำให้ผู้คนถึงกับตื่นตะลึง จู่ๆ โดยปราศจากคำเตือน กลุ่มชาวปาเลสไตน์หัวรุนแรง ที่รู้จักกันในชื่อ <B>"แบล็คเซปเทมเบอร์"</B> ได้บุกหมู่บ้านโอลิมปิค และลงมือสังหารสมาชิกสองคนของทีมโอลิมปิคอิสราเอล และยังจับตัวประกันเอาไว้อีก 9 ราย การสังหารหมู่ซึ่งเป็นโศกนาฏกรรม ที่ต่อมาได้ถูกนำเสนอผ่านทางโทรทัศน์ต่อหน้าคนทั่วโลก และสิ้นสุดในอีก 21 ชั่วโมงต่อมา เมื่อ <B>จิม แม็คเคย์</B> ได้กล่าวถ้อยคำที่ตามหลอกหลอนว่า <B>"พวกเขาตายหมดแล้ว"</B>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</P>\n<P>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ขณะที่ความสยดสยองที่เมืองมิวนิค กลายเป็นภาพที่ผู้คนได้เห็นและรู้สึกไปทั่วโลก ความลับหลังจากเหตุการณ์ดังกล่าว ยังคงไม่เป็นที่รับรู้ในวงกว้าง บัดนี้ จากฝีมือของผู้กำกับ สตีเว่น สปีลเบิร์ก ก็คือภาพยนตร์เรื่อง Munich ภาพยนตร์ทริลเลอร์ ที่อิงเรื่องราวจากเหตุการณ์ในเมืองนิวนิค ปี 1972 และภารกิจแก้แค้น ที่ติดตามมาโดยกลุ่มมือสังหาร ซึ่งเป็นที่รู้จักในหน่วยสืบราชการลับของอิสราเอลว่า <B>"ปฏิบัติการความพิโรธของพระเจ้า"</B> ซึ่งเป็นหนึ่งในแผนการสังหารที่รุนแรง และอาจหาญที่สุดในประวัติศาสตร์ยุคใหม่ ในรายละเอียดที่มีความชัดเจนและตึงเครียด ภาพยนตร์เรื่องนี้ นำพาคนดูไปสู่การเคลื่อนไหวอย่างลับๆ ครั้งหนึ่งในประวัติศาสตร์ ซึ่งเข้ากันได้ดี กับอารมณ์แบบเดียวกันในชีวิตของพวกเราในปัจจุบัน... </P>\n<P>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ใจกลางของเรื่องนี้ก็คือ <B>แอฟเนอร์ (อีริค บาน่า)</B> เจ้าหน้าที่หน่วยข่าวกรองหนุ่มชาวอิสราเอลผู้รักชาติ แอฟเนอร์ที่ยังคงเศร้าสลดไปกับเหตุการณ์สังหารโหดที่มิวนิค รู้สึกโกรธแค้นไปกับความรุนแรงของเหตุการณ์นี้ แอฟเนอร์ได้รับการติดต่อจากเจ้าหน้าที่มอสแซ็ดที่ชื่อ <B>เอเฟรม (เจฟฟรีย์ รัช)</B> ผู้เสนอให้เขาปฏิบัติภารกิจ ที่ไม่เคยมีมาก่อนในประวัติศาสตร์ของอิสราเอล เขาขอให้แอฟเนอร์ทิ้งภรรยาที่กำลังตั้งครรภ์เอาไว้เบื้องหลัง สละซึ่งตัวตน และแฝงตัวเพื่อปฏิบัติภารกิจตามล่า และลงมือฆ่าคนจำนวน 11 คน ที่ถูกกล่าวหาโดยหน่วยข่าวกรองของอิสราเอล ว่าเป็นผู้วางแผนเหตุการณ์สังหารโหดที่มิวนิค </P>\n<P>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;ถึงแม้จะยังหนุ่มและขาดประสบการณ์ แต่ในไม่ช้า แอฟเนอร์กลับกลายเป็นผู้นำของทีม ที่ประกอบไปด้วยสมาชิกสี่คน ที่มีความหหลากหลายแต่มีความสามารถสูง อันประกอบไปด้วย <B>สตีฟ (แดเนียล เคร็ก)</B> คนขับรถที่เกิดที่อัฟริกาใต้, <B>ฮานส์ (ฮานน์ส ซิสช์เลอร์)</B> ชาวเยอรมันเชื้อสายยิว ผู้มีความสามารถในการปลอมแปลงเอกสาร, <B>โรเบิร์ต (แมทธิว คาสโซวิตซ์)</B> ช่างทำของเล่นชาวเบลเยี่ยม ที่ผันตัวเองมาเป็นผู้เชี่ยวชาญด้านระเบิด และ <B>คาร์ล (เซียแรน ไฮนด์ส)</B> ผู้เงียบขรึม ซึ่งมีหน้าที่ทำความสะอาดร่องรอยของคนอื่นๆ </P>', 1, 13, 2, 2006, '11:27:24', '58.10.195.171', 'show', 'no', 'allow-show', 54, 35);
INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (109, '111', '<P style="MARGIN: 0px">222</P>', 1, 23, 2, 2006, '20:10:10', '161.246.5.92', 'show', 'no', 'allow-show', 0, 29);
INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (91, ': : Just Like Heaven : :', '<P><STRONG></STRONG>&nbsp;</P>\n<P align=center><STRONG><IMG src="http://media.movieweb.com/galleries/2798/posters/poster4_full.jpg"></P>\n<P style="MARGIN: 0px"><BR></STRONG>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เมื่อ เดวิด (มาร์ก รัฟฟาโล่) เช่าอพาร์ตเม้นต์ในซานฟรานซิสโก สิ่งสุดท้ายที่เขาคาดหวังจะได้เจอหรือต้องการ ก็คือเพื่อนร่วมห้อง เขาเพิ่งจะเริ่มสร้างความรกให้กับที่แห่งนี้ เมื่อหญิงสาวสวยจอมบงการที่ชื่อ เอลิซาเบธ (รีส วิเธอร์สปูน) ปรากฏตัวขึ้น พร้อมกับยืนยันว่า อพาร์ตเม้นต์แห่งนี้เป็นของเธอ เดวิดคาดว่าคงจะมีการเข้าใจผิดกันขนานใหญ่... จนกระทั่ง เอลิซาเบธหายตัวไปอย่างลึกลับเหมือนตอนมา การเปลี่ยนล็อคประตู ไม่อาจกีดกั้นเอลิซาเบธ ผู้เริ่มโผล่มา และหายไปตามอำเภอใจได้ ซึ่งส่วนมากแล้ว เธอจะโผล่มาเพื่อต่อว่าเดวิด ที่มาแสดงนิสัยส่วนตัวในอพาร์ตเม้นต์ของเธอ <BR><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เดวิดที่เชื่อว่าเอลิซาเบธเป็นผี พยายามช่วยให้เธอเดินทางข้ามไปยัง “อีกภพหนึ่ง” และถึงแม้เอลิซาเบธจะพบว่า เธอเป็นเหมือนอากาศธาตุ อาทิเช่น เธอสามารถเดินทะลุกำแพงได้ แต่เอลิซาเบธเชื่อว่าเธอยังมีชีวิตอยู่ และไม่จำเป็นต้องก้าวข้ามไปยังภพใดทั้งนั้น เมื่อเอลิซาเบธและเดวิด ช่วยกันออกค้นหาความจริงว่าเอลิซาเบธเป็นใคร และเธอเป็นอย่างที่เป็นอยู่ได้อย่างไร ความสัมพันธ์ของทั้งคู่ล้ำลึกมากขึ้น จนกลายเป็นความรัก โชคร้ายที่พวกเขามีเวลาเหลือน้อยเต็มที ก่อนที่ความหวังที่จะได้ใช้ชีวิตอยู่ด้วยกันอย่างถาวรในอนาคต ...เริ่มจางหายไป </P>\n<P style="MARGIN: 0px">&nbsp;</P>\n<P style="MARGIN: 0px">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<IMG style="WIDTH: 164px; HEIGHT: 149px" height=148 src="http://www.guidelive.com/feature/314/heaven.jpg" width=176><IMG style="WIDTH: 229px; HEIGHT: 151px" height=207 src="http://homepage.mac.com/merussell/iblog/B835531044/C969231614/E20050915172220/Media/justlikeheaven.jpg" width=294><BR><B><BR>นักแสดง</B> <BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; ทีมนักแสดงหลักยังประกอบไปด้วย โดนัล โล้ก (American Splendor, Confidenc, Reindeer Games, The Million Dollar Hotel, ผลงานทางทีวีเรื่อง ER), ไดน่า วอเตอร์ส (Freaky Friday, Full Frontal, John Q), เบน เชงแมน (Must Love Dogs, Requiem for a Dream, The Siege, Quiz Show, ผลงานของ HBO เรื่อง Angels in America) และ จอน เฮเดอร์ (Napoleon Dynamite) <BR><BR><BR><B>ทีมงาน</B> <BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; มาร์ก วอเตอร์ส ผู้กำกับภาพยนตร์เรื่อง Mean Girls, Head Over Heels และ Freaky Friday ภูมิใจเสนอผลงานใหม่ Just Like Heaven ภาพยนตร์ตลกโรแมนติค ที่นำแสดงโดย รีส วิเธอร์สปูน (Legally Blonde, Sweet Home Alabama, Election, Vanity Fair, Cruel Intentions, Pleasantville, Fear) และ มาร์ก รัฟฟาโล่ (13 Going on 30, Collateral, Eternal Sunshine of the Spotless Mind, My Life Without Me, View from the Top, You Can Count on Me) <BR></P>\n<P style="MARGIN: 0px" align=center><IMG src="http://www.funky.co.uk/entertainment/img/just_like_heaven_main.gif"><BR>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Just Like Heaven อำนวยการสร้างโดย ลอรี่ แม็คโดนัลด์ (The Ring, The Mask of Zorro) และ วอลเตอร์ เอฟ ปาร์กส์ (The Island, Gladiator) โดยมี เดวิด เฮ้าส์โฮลเตอร์ (Anchorman: The Legend of Ron Burgundy) ทำหน้าที่ผู้อำนวยการสร้างบริหาร มาร์ก วอเตอร์ส กำกับภาพยนตร์เรื่องนี้ จากบทภาพยนตร์ที่เขียนบทโดย ปีเตอร์ ทูแลน (Analyze This, Guess Who, America\\&#39;s Sweethearts, Bedazzled, Fun with Dick and Jane) และ เลสลี่ ดิ๊กซัน (Freaky Friday, Pay It Forward, The Thomas Crown Affair, Mrs. Doubtfire) โดยอิงจากนิยายเบสต์เซลเลอร์เรื่อง If Only It Were True ของนักเขียนนิยายชาวฝรั่งเศส มาร์ค เลวี่ย์ ผู้ทำหน้าที่เป็นผู้อำนวยการสร้างร่วม ของภาพยนตร์เรื่องนี้ด้วย</P>', 2, 22, 2, 2006, '18:04:53', '58.10.205.191', 'show', 'yes', 'notallow', 3, 35);
