INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (95, ': : Why not : :', '<div style="text-align: center; color: rgb(255, 255, 255); background-color: rgb(153, 0, 0);">Think <span style="color: rgb(255, 255, 153);">you</span>&#39;re going nowhere<br>when you&#39;re walking down the street<br><span style="color: rgb(255, 255, 153);">acting</span> like you just don&#39;t care<br>when life can be so <span style="color: rgb(255, 255, 153);">sweet</span><br>but why you wanna be like that<br>cause if there&#39;s nothin new<br>your not foolin&#39; no-one<br>you&#39;re not even foolin&#39; you<br><br>So walk a little slower<br>And open up your eyes<br>Sometimes it&#39;s so hard to see<br>The good things passing by<br>And there may never be a sign<br>No flashing neon light<br>Telling you to make your move<br>Or when the time is right<br><br>Chorus-----<br>(So) Why not? (Why not?)<br>Take a crazy chance<br>Why not? (Why not?)<br>Do a crazy dance<br>If you <span style="color: rgb(255, 204, 0);">lose</span> the moment<br>You might lose a lot<br>So why not?<br>(Why not?)<br><br>(Why not take a crazy chance, why not take a crazy chance)<br><br>You always dress in yellow<br>When you wanna dress in gold<br>Instead of listenin&#39; to your heart<br>You do just what you&#39;re told<br>You keep waiting where you are<br>And what you&#39;ll never <span style="color: rgb(255, 255, 0);">know</span><br>Let&#39;s just get into your car<br>And GO baby GO!<br><br>Chorus-----<br>(So) Why not? (Why not?)<br>Take a crazy chance<br>Why not? (Why not?)<br>Do a crazy dance<br>If you lose the moment<br>You might lose a lot<br>So why not?<br>(Why not?)<br><br>Ohhhhhhh<br>I can be the one for you<br>Ohhhh yea<br>Maybe yes maybe no<br><span style="color: rgb(255, 204, 0);">Ohhhhhhh</span><br>It could be the thing to do<br>What I&#39;m sayin&#39; is <br>Ya gotta let me know-o-o<br><br>(ay,ya etc.) Oh!<br><br>You&#39;ll never get to heaven<br>Or even to L.A.<br>If you don&#39;t believe<br>There&#39;s a wayyyy<br><br>Why not? (Why not?)<br>Take a star from the sky (echo)<br>Why not? (Why not?)<br>Spread your wings and fly<br>Oh!<br>It might take a little<br>And it might take a lot<br>But why not?<br>(Why not?)<br>Oh!<br><br>Why not? (Echo- take a crazy chance)<br>Take a crazy chance<br>Why not? (Echo-do a crazy dance)<br>Do a crazy dance<br>If you lose the moment<br>You might lose a lot<br>So why not?<br>(Why not?)<br>Yes Why not<br></div><div style="text-align: center;"></div>', 2, 22, 2, 2006, '18:41:25', '58.10.205.191', 'show', 'no', 'allow-hide', 11, 35);
