INSERT INTO `blog_content` (`content_id`, `topic`, `message`, `category_id`, `submit_day`, `submit_month`, `submit_year`, `submit_time`, `author_ip`, `is_show`, `is_recommend`, `comment_option`, `hits`, `author_user_id`) VALUES (97, 'Black Forest', '<table style="width: 520px; height: 250px;" align="left" background="http://album.romerun.com/hold_dm/folder/20463/album/33748/image/756145/pic/original.jpg" border="0" bordercolor="#ffffff" cellpadding="0" cellspacing="0"><tbody><tr><td align="left" valign="top"><div><font color="#808080"><strong>B</strong>lack Forest </font>คงเป็นชื่อเค้กที่หลายๆคนรู้จัก บางคนมักเข้าใจผิดคิดว่ามันคือเค้กช๊อคโกแลตเพราะสีมันดำๆเหมือนกัน</div><div>&nbsp;</div><div><font color="#ff0000">&nbsp;&nbsp;&nbsp;&nbsp; </font><font color="#808080"><strong>B</strong>lack Forest</font> มีต้นกำเนิดมาจาก ชาวเยอรมัน ซึ่งเรียกเจ้าเค้กชนิดนี้ว่า&nbsp; <font color="#800000">Schwarzwalder Kirsch Torte</font> ซึ่งมาจาก</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <font color="#800000"><strong>S</strong>chwarzwalder</font> หมายถึง ความมืดมิด ความน่าลึกลับ ที่มาจากความ Romantic ของคนเยอรมัน (ขนาดนั้น)</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;หรือมาจาก Concept ที่เรียกว่า Waldeinsamkeit&nbsp;( Forest-Loneliness )</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <font color="#800000"><font color="#800000"><strong>K</strong>irsch</font> </font>หมายถึง บรั่นดีที่ใช้ทำเค้ก โดย Black Forest นั้น จะใช้บรั่นดีรสเชอร์รี่เป็นส่วนผสม</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<font color="#800000">&nbsp;&nbsp; </font><font color="#800000"><strong>T</strong>orte</font> หมายถึง เค้ก ในภาษาของเยอรมันเค้าอะ (ได้ศัพท์เพิ่มอีกด้วย มีสาระจิงๆ)</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp; <strong>โ</strong>ดยสรุปก็ประมาณว่า Black Forest ก็คือ Layerเค้ก(เค้กที่มันเป็นชั้นๆ)ช๊อคโกแลตที่<strong>ผสมบรั่นดีเชอร์รี่</strong>&nbsp;</div><div>&nbsp;</div><div><strong>แ</strong>ล้วแต่งหน้าด้วย ครีม,&nbsp;Sour Cherry (&nbsp;ไอ้เชอร์รี่สีแดงๆที่เห็นกันทั่วไปอะ ไม่ใช่เยลลี่นะ) แล้วก็ช๊อคโกแลต</div><div>&nbsp;</div><div><font color="#ff0000"><strong>I</strong>ngredient :</font></div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp; <font color="#800000"><strong>C</strong>ake (เนื้อเค้ก) :</font></div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - ไข่ฟองใหญ่ 6 ฟอง&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - น้ำตาล<font color="#000000">ทราย</font>ขาว&nbsp; 1 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - วนิลา 1 ช้อนชา</div><div>&nbsp;</div><div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp;แป้ง 1 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<font color="#808080">&nbsp;&nbsp;&nbsp;-&nbsp;Unsweetened </font>Baking Chocolate&nbsp;ที่ละลายแล้ว 1/2 ถ้วย</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;&nbsp; <font color="#800000"><strong>S</strong>yrup (เพื่อเพิ่มรสให้กับ</font><font color="#800000">เนื้อแป้งอะนะ) :</font></div><div><font color="#800000">&nbsp;</font></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;<font color="#808080">&nbsp;-&nbsp;น้ำ 1/3 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - น้ำตาลทรายขาว&nbsp; 1/4 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </font>- บรั่นดีรสเชอร์รี่ 2 ช้อนชา</div><div>&nbsp;</div><div>&nbsp;&nbsp;&nbsp;<font color="#800000">&nbsp; <strong>F</strong>illing (ไอ้ที่เอาไว้ใส่กั้นระหว่าง Layer อะ) :</font></div><div><font color="#800000">&nbsp;</font></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <font color="#808080">- ไอซื่ง 1+1/2 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp;เนยจืด 1/3 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - ไข่ไก่ เอาเฉพาะไข่แดง 1 ฟอง</font></div><div><font color="#808080">&nbsp;</font></div><div><font color="#808080">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - บรั่นดีรสเชอร์รี่ 2 ช้อนชา</font></div><div><font color="#808080">&nbsp;</font></div><div>&nbsp;&nbsp;&nbsp;&nbsp;<font color="#800000"> <strong>T</strong>opping (พวกแต่งหน้าเค้กอะนะ) :</font></div><div><font color="#ffffff">&nbsp;</font></div><div><font color="#ffffff">&nbsp;</font>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; -&nbsp;Sour Cherry กระป๋อง <font color="#808080">2 ถ้วย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;</font>&nbsp; -&nbsp;ไอซิ่ง 2 ช้อนชา&nbsp;&nbsp;&nbsp;&nbsp;<font color="#808080">&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; <font color="#ffffff">- <font color="#ffffff">Wh</font>ipping Cream 1</font> ถ้วย</font></div><div><font color="#808080">&nbsp;</font></div><div>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; - Semisweet Chocolate 1 ถ้วย</div></div><p></p></td></tr></tbody></table>', 1, 23, 2, 2006, '03:48:06', '58.10.196.54', 'show', 'yes', 'allow-show', 1, 55);
