-- 
-- Table structure for table `user`
-- 

CREATE TABLE `user` (
  `user_id` int(10) NOT NULL auto_increment,
  `username` varchar(20) NOT NULL default '',
  `password` varchar(32) NOT NULL default '',
  `user_avatar` enum('no','file','url') NOT NULL default 'no',
  `alias_name` varchar(100) NOT NULL default '',
  `blog_title` varchar(200) NOT NULL default '',
  `email` varchar(100) NOT NULL default '',
  `regis_date` date NOT NULL default '0000-00-00',
  `credit_left` int(10) NOT NULL default '0',
  `last_login` datetime default NULL,
  `layout` char(2) NOT NULL default '1',
  `item_seq` varchar(255) NOT NULL default 'profile,category,archive,search,favourite,recommend,links,last_update, , , , , , , , , ,',
  `topic_per_page` int(10) NOT NULL default '5',
  `domain_id` int(10) NOT NULL default '0',
  PRIMARY KEY  (`user_id`),
  UNIQUE KEY `email` (`email`),
  UNIQUE KEY `username` (`username`)
) TYPE=MyISAM AUTO_INCREMENT=58 ;

