-- 
-- Table structure for table `user_css`
-- 

CREATE TABLE `user_css` (
  `user_id` int(10) NOT NULL default '0',
  `body_bg_color` varchar(7) NOT NULL default 'none',
  `body_bg_image` enum('no','file','url') NOT NULL default 'no',
  `body_border_style` varchar(7) NOT NULL default 'dashed',
  `body_border_color` varchar(7) NOT NULL default '#391D01',
  `header_bg_color` varchar(7) NOT NULL default '#391D01',
  `header_bg_image` enum('no','file','url') NOT NULL default 'no',
  `header_font_color` varchar(7) NOT NULL default '#FFFF99',
  `status_bg_color` varchar(7) NOT NULL default '#000000',
  `status_font_color` varchar(7) NOT NULL default '#FFFFFF',
  `item_bg_color` varchar(7) NOT NULL default 'none',
  `item_topic_bg_color` varchar(7) NOT NULL default '#4C2601',
  `item_topic_font_color` varchar(7) NOT NULL default '#FFFFCC',
  `item_link_color` varchar(7) NOT NULL default '#333333',
  `item_link_hover` varchar(7) NOT NULL default '#993300',
  `content_bg_color` varchar(7) NOT NULL default 'none',
  `content_comment_font_color` varchar(7) NOT NULL default '#FFFFCC',
  `content_blog_color` varchar(7) NOT NULL default 'none',
  `content_comment_bg_color` varchar(7) NOT NULL default '#663300',
  `comment_font_color` varchar(7) NOT NULL default '#333333',
  `comment_bg_color` varchar(7) NOT NULL default 'none',
  `comment_topic_font_color` varchar(7) NOT NULL default '#FFFFCC',
  `comment_topic_bg_color` varchar(7) NOT NULL default '#793C00',
  PRIMARY KEY  (`user_id`),
  UNIQUE KEY `user_id` (`user_id`)
) TYPE=MyISAM;

